import{_ as t}from"./chunks/collection-grid.JG5zeoci.js";import{_ as a,a as i,b as r,c as d,d as o}from"./chunks/dark-theme.DwSjXCKk.js";import{_ as l,o as s,c as h,a5 as c}from"./chunks/framework.-jms6n7v.js";const S=JSON.parse('{"title":"DaruDB Studio","description":"DaruDB Studio는 DaruDB 파일을 열어 컬렉션과 객체, 스키마를 보여 주는 Windows, macOS, Linux용 데스크톱 앱으로, 프로그램을 따로 짜지 않아도 파일 속 데이터를 고칠 수 있습니다.","frontmatter":{"title":"DaruDB Studio","order":15,"prev":{"text":"오류","link":"/ko/guide/errors"},"next":{"text":"엔진의 구조","link":"/ko/engine/architecture"}},"headers":[{"level":2,"title":"내려받기","slug":"내려받기","link":"#내려받기","children":[]},{"level":2,"title":"파일 열기","slug":"파일-열기","link":"#파일-열기","children":[]},{"level":2,"title":"객체 보고 고치기","slug":"객체-보고-고치기","link":"#객체-보고-고치기","children":[]},{"level":2,"title":"쿼리 실행하기","slug":"쿼리-실행하기","link":"#쿼리-실행하기","children":[]},{"level":2,"title":"스키마","slug":"스키마","link":"#스키마","children":[]},{"level":2,"title":"도구","slug":"도구","link":"#도구","children":[]},{"level":2,"title":"탭, 창, 테마","slug":"탭-창-테마","link":"#탭-창-테마","children":[]}],"relativePath":"ko/guide/studio.md","filePath":"ko/guide/studio.md","lastUpdated":1794204468000}'),n={name:"ko/guide/studio.md"};function u(p,e,m,g,_,b){return s(),h("div",null,[...e[0]||(e[0]=[c('<h1 id="darudb-studio" tabindex="-1">DaruDB Studio <a class="header-anchor" href="#darudb-studio" aria-label="Permalink to &quot;DaruDB Studio&quot;">​</a></h1><p>DaruDB Studio는 DaruDB 파일을 열어 컬렉션과 객체, 스키마를 보여 주는 Windows, macOS, Linux용 데스크톱 앱으로, 프로그램을 따로 짜지 않아도 파일 속 데이터를 고칠 수 있습니다.</p><img src="'+t+'" alt="샘플 쇼핑몰 데이터베이스를 연 DaruDB Studio. 사이드바에 컬렉션과 products의 필드가, 오른쪽 표에 products의 객체가 보입니다." width="1280" height="800"><p>앱은 스키마를 파일에서 직접 읽습니다. 그래서 어느 언어로 쓴 파일이든 엽니다. 파일을 읽고 쓸 때는 Node.js 패키지를 거치는데, 이 패키지도 다른 패키지와 같은 엔진을 쓰므로 앱에 보이는 내용이 곧 여러분의 프로그램이 읽는 내용입니다.</p><h2 id="내려받기" tabindex="-1">내려받기 <a class="header-anchor" href="#내려받기" aria-label="Permalink to &quot;내려받기&quot;">​</a></h2><p>설치 파일은 <a href="https://github.com/jooy2/darudb-studio" target="_blank" rel="noreferrer"><code>darudb-studio</code> 저장소</a>의 <a href="https://github.com/jooy2/darudb-studio/releases" target="_blank" rel="noreferrer">Releases 페이지</a>에 있습니다.</p><table tabindex="0"><thead><tr><th>운영체제</th><th>받을 파일</th></tr></thead><tbody><tr><td>Windows</td><td>설치 프로그램(<code>.exe</code>), 포터블 앱, <code>.zip</code>, <code>.appx</code> 패키지 중 하나(x64)</td></tr><tr><td>macOS</td><td>Apple 실리콘용, Intel용, 둘 다에서 도는 유니버설 <code>.dmg</code> 중 하나</td></tr><tr><td>Linux</td><td><code>.deb</code>, <code>.rpm</code>, <code>.snap</code> 패키지 중 하나(x64)</td></tr></tbody></table><p>소스 코드도 같은 저장소에 MIT 라이선스로 공개돼 있습니다. 버그 제보와 기능 제안은 저장소의 <a href="https://github.com/jooy2/darudb-studio/issues" target="_blank" rel="noreferrer">이슈</a>에 남겨 주세요.</p><h2 id="파일-열기" tabindex="-1">파일 열기 <a class="header-anchor" href="#파일-열기" aria-label="Permalink to &quot;파일 열기&quot;">​</a></h2><p>앱은 연 파일을 프로젝트로 기억합니다. 프로젝트에는 파일의 이름과 위치가 담기고, 원하면 암호화 키도 담깁니다. 키는 운영체제의 키 저장소가 암호화해 보관합니다. 확장자와 상관없이 어떤 파일이든 고를 수 있고, 앱은 DaruDB 데이터베이스인지 확인한 다음에 프로젝트로 남깁니다.</p><ul><li>암호화된 파일은 프로젝트에 기억된 키가 없거나, 기억된 키로 더는 열리지 않을 때 키를 묻습니다.</li><li>예전 형식 버전의 파일은 앱이 사본을 만들어 현재 버전으로 올린 뒤 열거나, 원본을 그 자리에서 올립니다. 어느 쪽인지는 직접 고릅니다. 파일을 올린다는 게 무슨 뜻인지는 <a href="./../engine/file-format#형식-버전">형식 버전</a>에 있습니다.</li><li>프로젝트 목록에서 작은 쇼핑몰의 샘플 데이터베이스도 열 수 있습니다. 모든 종류의 필드가 들어 있어서 내 파일 없이 앱을 둘러보기 좋습니다. 샘플은 열 때마다 앱 폴더에 새 파일로 만들어지고, 앱을 끄면 지워집니다.</li></ul><h2 id="객체-보고-고치기" tabindex="-1">객체 보고 고치기 <a class="header-anchor" href="#객체-보고-고치기" aria-label="Permalink to &quot;객체 보고 고치기&quot;">​</a></h2><p>컬렉션은 탭 하나에 표로 열립니다. 표는 객체를 한 페이지씩 읽어 오기 때문에 컬렉션이 커도 작은 컬렉션만큼 빠르게 스크롤됩니다. 열은 정렬하고 너비를 바꿀 수 있고, 표 위의 필터에는 <a href="./query-language">쿼리 언어</a>를 그대로 씁니다. 값은 타입마다 색이 다릅니다. 리스트와 내장 객체는 그 자리에서 펼쳐지고, 링크에는 가리키는 객체의 키가 보입니다.</p><p>값이 하나인 필드는 스프레드시트처럼 셀에서 바로 고칩니다. 객체 전체는 대화상자에서 고치는데, 리스트나 내장 객체는 항목과 필드로 된 폼으로 고쳐도 되고 JSON으로 고쳐도 됩니다. 날짜는 UTC 기준 RFC 3339 텍스트로 보이고, 같은 형식으로 입력합니다.</p><img src="'+a+'" alt="상품 하나를 고치는 대화상자. tags 리스트와 내장 객체 size가 폼으로 열려 있습니다." width="1280" height="800" loading="lazy"><p>고친 내용은 설정에 따라 바로 파일에 쓰이거나, 도구 모음에서 제출할 때까지 모아 둡니다. 모아 둔 변경은 제출하기 전까지 버릴 수 있습니다.</p><h2 id="쿼리-실행하기" tabindex="-1">쿼리 실행하기 <a class="header-anchor" href="#쿼리-실행하기" aria-label="Permalink to &quot;쿼리 실행하기&quot;">​</a></h2><p>쿼리 탭에서는 <code>SORT BY</code>와 <code>LIMIT</code>까지 포함한 쿼리 언어 문장을 통째로 실행합니다. 찾은 객체는 표로 나오고, 이 표에서도 컬렉션 탭과 똑같이 객체를 고칠 수 있습니다.</p><img src="'+i+'" alt="500 이상인 배송 완료 주문을 합계 순으로 찾은 쿼리 탭" width="1280" height="800" loading="lazy"><p><code>Database</code> 메뉴는 탭에 보이는 객체나 선택한 행만 CSV나 JSON으로 내보내고, 두 형식의 파일에서 객체를 컬렉션으로 가져옵니다. 가져올 때는 새로 추가하거나, 키가 같은 객체를 바꿔 씁니다. 가져오기는 트랜잭션 하나로 쓰기 때문에, 컬렉션에 맞지 않는 객체가 하나라도 있으면 아무것도 들어가지 않습니다.</p><h2 id="스키마" tabindex="-1">스키마 <a class="header-anchor" href="#스키마" aria-label="Permalink to &quot;스키마&quot;">​</a></h2><p>사이드바에는 파일에 있는 컬렉션이 객체 수와 함께 나오고, 컬렉션마다 키와 필드, 필드의 타입, 인덱스가 나옵니다. 스키마 대화상자는 Node.js 패키지로 이 스키마를 선언하는 TypeScript 코드나 JSON을 보여 줍니다. 프로그램에 복사해 넣거나 파일로 저장할 수 있습니다.</p><img src="'+r+'" alt="샘플 데이터베이스의 스키마를 선언하는 TypeScript 코드" width="1280" height="800" loading="lazy"><p>컬렉션과 필드는 사이드바에서 추가하고, 이름을 바꾸고, 지웁니다. 바꿀 때마다 엔진이 마이그레이션을 실행해 파일에 저장된 스키마 버전을 하나 올립니다. 원하면 바꾸기 전에 파일을 백업합니다.</p><div class="warning custom-block"><p class="custom-block-title">예전 버전을 선언한 프로그램은 파일을 열지 못합니다</p><p>앱에서 스키마를 바꾸면 파일의 스키마 버전이 프로그램이 선언한 버전보다 높아지고, 프로그램이 파일을 열 때 <code>SCHEMA_TOO_NEW</code>로 실패합니다. 파일을 다시 열기 전에 프로그램에서도 새 버전과 같은 컬렉션, 필드를 선언하세요. 규칙은 <a href="./migrations#여러-버전을-한-번에">여러 버전을 한 번에</a>에 있습니다.</p></div><h2 id="도구" tabindex="-1">도구 <a class="header-anchor" href="#도구" aria-label="Permalink to &quot;도구&quot;">​</a></h2><p>도구 탭에서는 패키지의 <a href="./tools">도구</a>가 하는 일을 열린 파일에 그대로 합니다. 무결성을 검사하고, 파일을 압축하고, 백업을 씁니다. 백업은 원하면 별도 암호화 키로 암호화합니다. 암호화된 파일이라면 키도 바꿀 수 있습니다.</p><img src="'+d+'" alt="무결성 검사에서 문제를 찾지 못하고 압축을 마친 도구 탭" width="1280" height="800" loading="lazy"><p>손상된 파일은 아직 읽을 수 있는 객체를 모두 새 파일로 옮겨 복구하고, 앱은 그 파일을 새 프로젝트로 추가합니다. 복구는 도구 탭에서 할 수 있고, 손상 때문에 파일이 열리지 않을 때도 앱이 먼저 권합니다. 손상된 원본 파일은 건드리지 않습니다.</p><h2 id="탭-창-테마" tabindex="-1">탭, 창, 테마 <a class="header-anchor" href="#탭-창-테마" aria-label="Permalink to &quot;탭, 창, 테마&quot;">​</a></h2><p>탭은 그룹으로 나눠 나란히 놓고, 그룹 사이로 옮기고, 다시 합칠 수 있습니다. 창 하나에는 프로젝트 하나가 열리고, 앱을 한 번 더 실행하면 이미 실행 중인 앱에 창이 하나 더 열립니다. 설정에서 켜 두면 마지막으로 앱을 끌 때 열려 있던 창과 프로젝트, 탭을 다음 실행 때 다시 엽니다.</p><img src="'+o+'" alt="상품과 배송 중인 주문을 두 탭 그룹에 나란히 띄운 어두운 테마 화면" width="1280" height="800" loading="lazy"><p>앱은 영어, 독일어, 프랑스어, 일본어, 한국어로 쓸 수 있고, 밝은 테마와 어두운 테마가 있습니다. 둘 다 설정에서 고르기 전까지는 운영체제 설정을 따릅니다.</p>',33)])])}const x=l(n,[["render",u]]);export{S as __pageData,x as default};
